              double Ynew_i = S_61 + ros_M1 * K1_61 + ros_M2 * K2_61 + ros_M3 * K3_61;
              double ymax = Kokkos::fmax(Kokkos::fabs(state(61)), Kokkos::fabs(Ynew_i));
